```csharp
using System;

class Program
{
    static void Main()
    {
        Random rand = new Random();
        int numberToGuess = rand.Next(1, 101); // generate a random number between 1 and 100
        int guess;
        int numGuesses = 0;
        int min = 1;
        int max = 100;

        Console.WriteLine("Guess a number between 1 and 100.");

        do
        {
            Console.Write($"Guess #{numGuesses+1}: ");
            guess = int.Parse(Console.ReadLine());
            numGuesses++;

            if (guess < numberToGuess)
            {
                Console.WriteLine("Too low!");
                min = guess + 1; // eliminate the lower half of the range
            }
            else if (guess > numberToGuess)
            {
                Console.WriteLine("Too high!");
                max = guess - 1; // eliminate the upper half of the range
            }
            else
            {
                Console.WriteLine($"Congratulations! You guessed the number {numberToGuess} in {numGuesses} guesses.");
                break;
            }

            // binary search algorithm
            guess = (min + max) / 2;

        } while (guess != numberToGuess);

        Console.WriteLine("Press any key to exit.");
        Console.ReadKey();
    }
}
```
