#include "geometry_msgs/msg/twist_stamped.hpp"
#include "sensor_msgs/msg/laser_scan.hpp"

#include "particle_filter/particle_filter.hpp"

class ParticleFilterNode : public rclcpp::Node
{
public:
  ParticleFilterNode(const rclcpp::NodeOptions & options)
  : Node("particle_filter_node", options),
    filter_(std::make_shared<ParticleFilter>())
  {
    // Set up the laser scan subscriber
    laser_scan_sub_ = this->create_subscription<sensor_msgs::msg::LaserScan>(
      "laser_scan", rclcpp::QoS(10),
      std::bind(&ParticleFilterNode::laser_scan_callback, this, std::placeholders::_1));

    // Set up the velocity command subscriber
    velocity_command_sub_ = this->create_subscription<geometry_msgs::msg::TwistStamped>(
      "velocity_command", rclcpp::QoS(10),
      std::bind(&ParticleFilterNode::velocity_command_callback, this, std::placeholders::_1));

    // Set up the pose estimate publisher
    pose_estimate_pub_ = this->create_publisher<geometry_msgs::msg::PoseStamped>(
      "pose_estimate", rclcpp::QoS(10));
  }

private:
  // Callback for the laser scan data
  void laser_scan_callback(const sensor_msgs::msg::LaserScan::SharedPtr msg)
  {
    // Update the particle filter with the new laser scan data
    filter_->update(msg->ranges);
  }

  // Callback for the velocity command
  void velocity_command_callback(const geometry_msgs::msg::TwistStamped::SharedPtr msg)
  {
    // Update the particle filter with the new velocity command
    filter_->predict(msg->twist.linear.x, msg->twist.angular.z);
  }

