  rclcpp::Subscription<geometry_msgs::msg::TwistStamped>::SharedPtr velocity_command_sub_;
  rclcpp::Publisher<geometry_msgs::msg::PoseStamped>::SharedPtr pose_estimate_pub_;

  std::shared_ptr<ParticleFilter> filter_;
};

int main(int argc, char ** argv)
{
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<ParticleFilterNode>(rclcpp::NodeOptions()));
  rclcpp::shutdown();
  return 0;
}
