```perl
# Import the Active Directory module
Import-Module ActiveDirectory

# Set the path and name of the CSV file to be created
$csvPath = "C:\SIDHistory.csv"

# Define the properties to be included in the CSV file
$properties = "samAccountName", "SID", "SIDHistory"

# Get all users and groups within the domain
$objects = Get-ADObject -Filter {ObjectClass -eq "user" -or ObjectClass -eq "group"} -Properties SID,SIDHistory

# Create an array to store the data for each user or group
$data = @()

# Loop through each user or group and add its data to the array
foreach ($object in $objects) {
    # Check if the object has a SIDHistory attribute
    if ($object.SIDHistory) {
        # Loop through each SID in the SIDHistory attribute
        foreach ($sid in $object.SIDHistory) {
            # Create a custom object with the user or group's data
            $data += [PSCustomObject] @{
                "samAccountName" = $object.samAccountName
                "SID" = $object.SID
                "SIDHistory" = $sid
            }
        }
    } else {
        # Create a custom object with the user or group's data
        $data += [PSCustomObject] @{
            "samAccountName" = $object.samAccountName
            "SID" = $object.SID
            "SIDHistory" = $null
        }
    }
}

# Export the data to a CSV file
$data | Select-Object $properties | Export-Csv $csvPath -NoTypeInformation
```
